const choices = ['rock', 'paper', 'scissors'];
const icons = {
  rock: '✊',
  paper: '✋',
  scissors: '✌️'
};

const playerScoreEl = document.getElementById('player-score');
const computerScoreEl = document.getElementById('computer-score');
const playerHandEl = document.getElementById('player-hand');
const computerHandEl = document.getElementById('computer-hand');
const roundResultEl = document.getElementById('round-result');
const resetBtn = document.getElementById('reset-btn');
const choiceButtons = document.querySelectorAll('.choice-btn');

const STORAGE_KEY = 'rps_game_scores_v1';

let scores = { player: 0, computer: 0 };

function loadScores() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      scores = JSON.parse(saved);
      playerScoreEl.textContent = scores.player;
      computerScoreEl.textContent = scores.computer;
    }
  } catch (e) {
    console.warn('Failed to load scores:', e);
  }
}

function saveScores() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(scores));
  } catch (e) {
    console.warn('Failed to save scores:', e);
  }
}

function getComputerChoice() {
  const randomIndex = Math.floor(Math.random() * choices.length);
  return choices[randomIndex];
}

function playRound(playerChoice) {
  const computerChoice = getComputerChoice();

  playerHandEl.textContent = icons[playerChoice];
  computerHandEl.textContent = icons[computerChoice];

  if (playerChoice === computerChoice) {
    roundResultEl.textContent = "It's a tie!";
    roundResultEl.className = 'round-result';
  } else if (
    (playerChoice === 'rock' && computerChoice === 'scissors') ||
    (playerChoice === 'paper' && computerChoice === 'rock') ||
    (playerChoice === 'scissors' && computerChoice === 'paper')
  ) {
    scores.player++;
    playerScoreEl.textContent = scores.player;
    roundResultEl.textContent = `You win! ${playerChoice} beats ${computerChoice}.`;
    roundResultEl.className = 'round-result win';
    saveScores();
  } else {
    scores.computer++;
    computerScoreEl.textContent = scores.computer;
    roundResultEl.textContent = `You lose! ${computerChoice} beats ${playerChoice}.`;
    roundResultEl.className = 'round-result lose';
    saveScores();
  }
}

function resetGame() {
  scores = { player: 0, computer: 0 };
  playerScoreEl.textContent = '0';
  computerScoreEl.textContent = '0';
  playerHandEl.textContent = '❓';
  computerHandEl.textContent = '❓';
  roundResultEl.textContent = 'Choose your move to start!';
  roundResultEl.className = 'round-result';
  saveScores();
}

choiceButtons.forEach(btn => {
  btn.addEventListener('click', () => {
    const choice = btn.dataset.choice;
    playRound(choice);
  });
});

resetBtn.addEventListener('click', resetGame);
loadScores();

:root {
  --bg-color: #0b0f19;
  --card-bg: #151c2e;
  --primary: #a855f7;
  --primary-hover: #9333ea;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --border: #232f48;
  --win-color: #22c55e;
  --lose-color: #ef4444;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.game-container {
  background-color: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 1.25rem;
  width: 100%;
  max-width: 500px;
  padding: 2rem;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5);
  text-align: center;
}

.game-header {
  margin-bottom: 2rem;
}

.game-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 1.25rem;
}

.score-board {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.5rem;
  background: #0b0f19;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  padding: 0.75rem 1.5rem;
  width: fit-content;
  margin: 0 auto;
}

.score-card {
  display: flex;
  flex-direction: column;
}

.score-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--text-muted);
}

.score-value {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--text-main);
}

.score-divider {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--border);
}

.choices-container {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 2rem;
}

.choice-btn {
  background: #0b0f19;
  border: 2px solid var(--border);
  border-radius: 1rem;
  width: 5rem;
  height: 5rem;
  font-size: 2.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: transform 0.15s, border-color 0.15s, background-color 0.15s;
}

.choice-btn:hover {
  transform: translateY(-4px);
  border-color: var(--primary);
  background: #1a233a;
}

.battle-display {
  background: #0b0f19;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  padding: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.5rem;
}

.hand-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  flex: 1;
}

.hand-label {
  font-size: 0.7rem;
  color: var(--text-muted);
  text-transform: uppercase;
}

.hand-icon {
  font-size: 2.5rem;
}

.status-box {
  flex: 1.2;
}

.round-result {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-main);
}

.round-result.win {
  color: var(--win-color);
}

.round-result.lose {
  color: var(--lose-color);
}

.game-footer {
  border-top: 1px solid var(--border);
  padding-top: 1.25rem;
}

.reset-button {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-muted);
  padding: 0.5rem 1.25rem;
  border-radius: 0.5rem;
  font-size: 0.8125rem;
  cursor: pointer;
  transition: all 0.2s;
}

.reset-button:hover {
  border-color: var(--primary);
  color: var(--text-main);
}
